        font-size: clamp(1.7rem, 4vw, 2.5rem);
      }

      .section-head p {
        margin: 0;
        max-width: 38ch;
        color: var(--muted);
        line-height: 1.6;
      }

      .grid {
        display: grid;
        gap: 1.2rem;
      }

      .products-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .deals-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .stories-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .content-card {
        padding: 1rem;
      }

      .product-art,
      .story-art,
      .deal-art {
        border-radius: var(--radius-lg);
        min-height: 14rem;
        margin-bottom: 1rem;
      }

      .product-art {
        background:
          radial-gradient(circle at 70% 20%, #f4d6b3 0, #f4d6b3 15%, transparent 34%),
