          radial-gradient(circle at top right, rgba(255, 242, 222, 0.7) 0, rgba(255, 242, 222, 0.7) 18%, transparent 36%),
          linear-gradient(135deg, rgba(30, 77, 67, 0.12), rgba(255, 255, 255, 0.94));
