        display: inline-block;
        margin-bottom: 0.4rem;
        font-weight: 700;
      }

      .field-note {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .input-row {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        gap: 0.75rem;
      }

      input[type="email"] {
        width: 100%;
        min-height: 3rem;
        padding: 0.8rem 1rem;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: #fff;
        color: var(--text);
      }

      .status {
        min-height: 1.5rem;
