        }

        .hero h1 {
          max-width: none;
        }

        .site-nav ul {
          gap: 0.35rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        body,
        .hero-copy,
        .hero-panel,
        .content-card,
        .deal-banner,
        .newsletter-copy,
        .newsletter-form,
        .footer-card {
          background: Canvas;
          color: CanvasText;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .button,
        .pill,
        input[type="email"] {
          background: Canvas;
          color: ButtonText;
          border: 1px solid ButtonBorder;
        }

        a:focus-visible,
        button:focus-visible,
        input:focus-visible {
