        }
      }
    </style>
  </head>
  <body id="top">
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const featuredProducts = [
        {
          name: "Cloudline Overshirt",
          category: "New arrival",
          price: "$148",
          description: "A softly structured layer cut for weekday polish and weekend ease.",
          accentClass: "pill-accent"
        },
        {
          name: "Arc Leather Weekender",
          category: "Best seller",
          price: "$224",
          description: "Premium carryall with clean hardware and room for a two-day reset.",
          accentClass: "pill-warm"
        },
        {
          name: "Studio Lounge Chair",
          category: "Home edit",
          price: "$389",
          description: "Low-profile comfort in a sculpted silhouette made for reading corners.",
          accentClass: "pill-accent"
        },
        {
          name: "Monarch Runner",
          category: "Limited drop",
          price: "$132",
          description: "Everyday sneakers tuned for light support, texture, and all-day wear.",
          accentClass: "pill-warm"
        }
      ];

      const deals = [
        {
          title: "Weekend living refresh",
          offer: "Save 30%",
          detail: "Layered textiles, lighting, and tabletop pieces for the season ahead.",
          code: "HOME30",
          compareAt: "$240",
          price: "$168"
        },
        {
          title: "Travel-ready essentials",
          offer: "Bundle pricing",
          detail: "Pick any bag and accessories set for a faster, smarter getaway pack.",
          code: "PACKLIGHT",
          compareAt: "$198",
          price: "$154"
        },
        {
          title: "Editorial favorites",
          offer: "Ends Sunday",
          detail: "Shop the products featured in this week's journal and styling guides.",
          code: "EDIT15",
          compareAt: "$120",
          price: "$102"
        }
      ];

      const stories = [
        {
          title: "How to build a calmer entryway",
          category: "Journal",
          description: "Storage, texture, and soft lighting tips that make every arrival feel intentional.",
          cta: "Read story"
        },
        {
          title: "The modern capsule wardrobe checklist",
          category: "Style guide",
          description: "A practical edit of pieces that combine easily and still feel distinctly current.",
          cta: "Explore the guide"
        },
        {
          title: "Behind the materials in our spring line",
          category: "Editorial",
          description: "A closer look at the woven blends, finishes, and construction choices shaping the drop.",
          cta: "Meet the makers"
        }
      ];

      const Header = () => `
        <header class="site-header">
          <div class="page-shell header-bar">
            <a href="#top" class="brand" aria-label="Northstar Goods home">
              <span class="brand-mark" aria-hidden="true">N</span>
              <span>Northstar Goods</span>
            </a>
            <nav class="site-nav" aria-label="Primary">
              <ul>
                <li><a href="#featured-products">Featured</a></li>
                <li><a href="#today-deals">Deals</a></li>
                <li><a href="#editorial-stories">Editorial</a></li>
                <li><a href="#member-edit">Member edit</a></li>
              </ul>
            </nav>
          </div>
        </header>
      `;

      const Hero = () => `
        <section class="hero" aria-labelledby="home-title">
          <div class="hero-copy">
            <span class="eyebrow">Season launch</span>
            <h1 id="home-title">Retail essentials with a softer edge.</h1>
            <p>
              Discover elevated apparel, home accents, and everyday objects designed to make your
              space feel considered and your routine feel lighter.
            </p>
            <div class="hero-actions">
              <a class="button button-primary" href="#featured-products">Shop featured picks</a>
              <a class="button button-secondary" href="#editorial-stories">Browse the journal</a>
            </div>
            <div class="hero-stats" aria-label="Highlights">
              <div class="hero-stat">
                <strong>48h</strong>
                <span>Fast delivery on curated picks</span>
              </div>
              <div class="hero-stat">
                <strong>120+</strong>
                <span>Fresh styles across apparel and home</span>
              </div>
              <div class="hero-stat">
                <strong>4.8/5</strong>
                <span>Average rating from returning shoppers</span>
              </div>
            </div>
          </div>
          <aside class="hero-panel" aria-label="Featured highlight">
            <div class="hero-visual" aria-hidden="true"></div>
            <div class="hero-note">
              <span class="section-eyebrow">Editor pick</span>
              <strong>The Soft Weekend Edit</strong>
              <p>
                Layerable knits, sculpted seating, and warm neutrals chosen to anchor a cleaner home
                and wardrobe story.
              </p>
              <a class="button button-secondary" href="#member-edit">Shop now</a>
            </div>
          </aside>
        </section>
      `;

      const SectionHead = (eyebrow, title, body, actionHref, actionLabel) => `
        <div class="section-head">
          <div>
            <span class="section-eyebrow">${eyebrow}</span>
            <h2>${title}</h2>
          </div>
          <div>
            <p>${body}</p>
            ${actionHref && actionLabel ? `<a class="button button-secondary" href="${actionHref}">${actionLabel}</a>` : ""}
          </div>
        </div>
      `;

      const ProductCard = (product) => `
        <article class="content-card product-card">
          <div class="product-art" aria-hidden="true"></div>
          <div class="card-topline">
            <span class="pill ${product.accentClass}">${product.category}</span>
            <span class="price">${product.price}</span>
          </div>
          <h3>${product.name}</h3>
          <p>${product.description}</p>
          <a class="button button-primary" href="#member-edit" aria-label="Add to cart: ${product.name}">Add to cart</a>
        </article>
      `;

      const DealCard = (deal) => `
        <article class="content-card deal-card">
          <div class="deal-art" aria-hidden="true"></div>
          <div class="deal-topline">
            <span class="pill pill-warm">${deal.offer}</span>
            <span class="pill">Code: ${deal.code}</span>
          </div>
          <h3>${deal.title}</h3>
          <p>${deal.detail}</p>
          <div class="price-row" aria-label="Sale pricing">
            <span class="price">${deal.price}</span>
            <span class="price-compare">${deal.compareAt}</span>
          </div>
          <a class="button button-secondary" href="#member-edit" aria-label="Shop deal: ${deal.title}">Shop deal</a>
        </article>
      `;

      const StoryCard = (story) => `
        <article class="content-card story-card">
          <div class="story-art" aria-hidden="true"></div>
          <div class="card-topline">
            <span class="pill pill-accent">${story.category}</span>
          </div>
          <h3>${story.title}</h3>
          <p>${story.description}</p>
          <a class="button button-secondary" href="#member-edit" aria-label="${story.cta}: ${story.title}">${story.cta}</a>
        </article>
      `;

      const DealBanner = () => `
        <section class="deal-banner" id="member-edit" aria-labelledby="member-edit-title">
          <div>
            <span class="section-eyebrow">Member edit</span>
            <h2 id="member-edit-title">A polished home page built for browsing and buying.</h2>
            <p>
              The member collection pairs understated palette choices with tactile materials and
              quiet statements, giving shoppers a landing page that feels premium without feeling busy.
            </p>
          </div>
          <div class="banner-pills" aria-label="Member benefits">
            <span class="pill"><strong>Free returns</strong>&nbsp;30 days</span>
            <span class="pill"><strong>Member price</strong>&nbsp;Early access</span>
            <span class="pill"><strong>Store pickup</strong>&nbsp;Same day</span>
          </div>
        </section>
      `;

      const Newsletter = () => `
        <section class="newsletter" aria-labelledby="newsletter-title">
          <div class="newsletter-copy">
            <span class="section-eyebrow">Stay in the loop</span>
            <h2 id="newsletter-title">Get first access to launches, offers, and styling notes.</h2>
            <p class="footer-copy">
              Sign up for a concise weekly dispatch with product drops, limited-run deals, and fresh
              editorial picks from the Northstar team.
            </p>
          </div>
          <div class="newsletter-form">
            <form id="newsletter-form" novalidate>
              <div>
                <label class="field-label" for="email">Email address <span aria-hidden="true">*</span></label>
                <p class="field-note" id="email-note">Required for weekly updates and launch access.</p>
              </div>
              <div class="input-row">
                <input
                  id="email"
                  name="email"
                  type="email"
                  autocomplete="email"
                  required
                  aria-required="true"
                  aria-describedby="email-note email-status"
                />
                <button class="button button-primary" type="submit">Join now</button>
              </div>
              <p class="status" id="email-status" aria-live="polite"></p>
            </form>
          </div>
        </section>
      `;

      const Footer = () => `
        <footer class="site-footer">
          <div class="page-shell">
            <div class="footer-card">
              <p class="footer-copy">Northstar Goods designs a quieter, more intentional way to shop home and wardrobe essentials.</p>
              <nav aria-label="Footer">
                <div class="footer-links">
                  <a href="#featured-products">Featured</a>
                  <a href="#today-deals">Deals</a>
                  <a href="#editorial-stories">Editorial</a>
                </div>
              </nav>
            </div>
          </div>
        </footer>
      `;

      const App = () => `
        ${Header()}
        <main id="main-content" tabindex="-1">
          <div class="page-shell">
            ${Hero()}
            <section id="featured-products" aria-labelledby="featured-products-title">
              ${SectionHead(
                "Featured products",
                "Curated pieces that carry the whole room or outfit.",
                "A mix of top-performing staples and just-landed arrivals, selected to feel cohesive across categories.",
                "#member-edit",
                "View all featured"
              ).replace("<h2>", '<h2 id="featured-products-title">')}
              <div class="grid products-grid">
                ${featuredProducts.map(ProductCard).join("")}
              </div>
            </section>
            ${DealBanner()}
            <section id="today-deals" aria-labelledby="today-deals-title">
              ${SectionHead(
                "Today only",
                "Deals designed to feel premium, not promotional.",
                "Discounts stay intentional here: fewer offers, stronger curation, and clearer value for shoppers ready to act.",
                "#member-edit",
                "See all offers"
              ).replace("<h2>", '<h2 id="today-deals-title">')}
              <div class="grid deals-grid">
                ${deals.map(DealCard).join("")}
              </div>
            </section>
            <section id="editorial-stories" aria-labelledby="editorial-stories-title">
              ${SectionHead(
                "Editorial content",
                "Stories that help products feel lived in before checkout.",
                "Use content to turn browsing into confidence with styling ideas, maker notes, and practical inspiration.",
                "#member-edit",
                "Open the journal"
              ).replace("<h2>", '<h2 id="editorial-stories-title">')}
              <div class="grid stories-grid">
                ${stories.map(StoryCard).join("")}
              </div>
            </section>
            ${Newsletter()}
          </div>
        </main>
        ${Footer()}
      `;

      document.getElementById("app").innerHTML = App();

      const form = document.getElementById("newsletter-form");
      const email = document.getElementById("email");
      const status = document.getElementById("email-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!email.validity.valid) {
          email.setAttribute("aria-invalid", "true");
          status.textContent = "Enter a valid email address to join the list.";
          email.focus();
          return;
        }

        email.removeAttribute("aria-invalid");
        status.textContent = "Thanks for joining. You're on the list for new drops and offers.";
