              ).replace("<h2>", '<h2 id="editorial-stories-title">')}
              <div class="grid stories-grid">
                ${stories.map(StoryCard).join("")}
              </div>
            </section>
            ${Newsletter()}
          </div>
        </main>
        ${Footer()}
      `;

